parameters.jsCode:
// =====================================================================
// EVERWAKE — Main · NODE: Check Reply
//
// NEVER rewrites the host's words. It only checks hard rails, and a
// broken rail sends the draft to one rewrite (no tools — nothing can be
// added to the cart twice) with the exact reason:
//   · a number that is not a real price / total / fee / detail on file
//   · saying the order is placed when place_order did not return PLACED
//   · saying a table booking is confirmed (only the branch team confirms)
//   · internal codes, ids or tool names leaking to the customer
//   · a link that is not the restaurant's or the customer's own
//   · menu pictures or a dish photo promised when none is being sent
//   · far too long for WhatsApp
// Facts it may ADD without asking: the order number after a placement,
// or the booking's reference after it was sent, when the host forgot it.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
// ---- shared: Arabic-aware matching (same rules as everwake.norm in SQL) --
function normalizeArabic(s) {
  return String(s == null ? '' : s).toLowerCase()
    .replace(/[ً-ٰٟـ]/g, '')
    .replace(/[أإآٱ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه')
    .replace(/[٠-٩]/g, d => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)))
    .replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim();
}
const toWesternDigits = (s) => String(s == null ? '' : s).replace(/[٠-٩]/g, d => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)));
const pre = $('Attach Plan').first().json;
const agent = $('Agent').first().json || {};
const ctx = row($('Load Turn Context').first().json);
const db = row($input.first().json);

const r2 = (n) => Math.round(num(n) * 100) / 100;

// ---- the decision ------------------------------------------------------------
let decision = agent.output ?? agent.response ?? agent.text ?? null;
if (decision && typeof decision === 'object' && decision.output && typeof decision.output === 'object') decision = decision.output;
if (typeof decision === 'string') {
  const s = decision.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  const a = s.indexOf('{'), z = s.lastIndexOf('}');
  try { decision = a !== -1 && z > a ? JSON.parse(s.slice(a, z + 1)) : { reply_messages: [decision] }; }
  catch (e) { decision = { reply_messages: [decision] }; }
}
decision = obj(decision);

// ---- what the tools did ----------------------------------------------------------
const steps = arr(agent.intermediateSteps ?? agent.intermediate_steps);
const toolsUsed = [];
let placedNo = null, placedTotal = null;
const toolNumbers = [];
const toolProblems = [];
const bookingTexts = [];
let bookingRef = null;
for (const st of steps) {
  const tool = str(obj(obj(st).action).tool);
  if (tool) toolsUsed.push(tool);
  let o = obj(st).observation;
  try { o = typeof o === 'string' ? JSON.parse(o) : o; } catch (e) { o = null; }
  if (Array.isArray(o)) o = o[0];
  if (!o || typeof o !== 'object') continue;
  if (o.response && typeof o.response === 'string') { try { o = JSON.parse(o.response); } catch (e) {} }
  if (tool === 'manage_reservation') {
    // the booking's day, time, guests, phone and reference are facts the host may repeat
    bookingTexts.push(JSON.stringify(o));
    if (str(o.status) === 'REQUESTED' && o.ref_no) bookingRef = str(o.ref_no);
    for (const p of arr(o.problems)) toolProblems.push(p);
    continue;
  }
  if (str(o.status) === 'PLACED' && o.order_no) { placedNo = str(o.order_no); placedTotal = o.total; }
  for (const k of ['subtotal', 'discount_total', 'vat', 'vat_percent', 'delivery_fee', 'total', 'minimum', 'short_by'])
    if (o[k] != null) toolNumbers.push(num(o[k]));
  for (const l of arr(o.cart)) if (l && l.line_total != null) toolNumbers.push(num(l.line_total));
  for (const a of arr(o.offers_applied)) if (a && a.amount != null) toolNumbers.push(num(a.amount));
  for (const a of arr(o.offers_almost)) if (a && a.short_by != null) toolNumbers.push(num(a.short_by));
  for (const p of arr(o.problems)) { toolProblems.push(p); for (const k of ['shortfall', 'minimum', 'price']) if (p && p[k] != null) toolNumbers.push(num(p[k])); }
}

// ---- messages: split, tidy ------------------------------------------------------------
let messages = arr(decision.reply_messages ?? decision.reply_text ?? decision.messages)
  .map(x => str(x)).filter(Boolean)
  .flatMap(m => m.split(/^\s*\[\[\s*NEXT\s*\]\]\s*$/m).map(x => x.trim()).filter(Boolean));
const HEARTS = /[❣❤♥\u{1F493}-\u{1F49F}\u{1F5A4}\u{1F90D}\u{1F90E}\u{1F60D}\u{1F970}\u{1F618}\u{1F61A}\u{1F617}\u{1F619}\u{1F63B}\u{1F48B}\u{1F491}\u{1F495}]\u{FE0F}?/gu;
let heartsStripped = 0;
messages = messages.map(m => {
  heartsStripped += (m.match(HEARTS) || []).length;
  return m.replace(HEARTS, '')
    .replace(/\*\*(.+?)\*\*/g, '*$1*')           // WhatsApp bold is one asterisk
    .replace(/^#{1,6}\s+/gm, '')                  // no markdown headings
    .replace(/\[\[\s*NEXT\s*\]\]/g, '')
    .replace(/[ \t]{2,}/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
}).filter(Boolean);
if (messages.length > 2) messages = [messages[0], messages.slice(1).join('\n\n')];

// ---- facts after the tools ---------------------------------------------------------------
const state = obj(db.state);
const ledger = obj(state.ledger);
const location = obj(state.location);
const zone = obj(state.zone);
const order = db.active_order && db.active_order !== 'null' ? obj(db.active_order) : {};
const items = arr(obj(order.cart).items);
const pending = arr(ledger.pending_items);
const branchLookup = obj(db.branch_lookup);
const allLookup = obj(ctx.all_lookup);
const settings = obj(allLookup.settings);
const profile = obj(allLookup.profile);
const media = obj(allLookup.media);
const branchId = str(obj(state.branch).id);

// ---- numbers the host may say ------------------------------------------------------------
const allowed = new Set();
const add = (n) => { if (Number.isFinite(n)) { allowed.add(r2(n)); allowed.add(Math.round(n)); } };
const addDigits = (s) => { for (const m of toWesternDigits(s).match(/\d+(?:\.\d+)?/g) || []) add(Number(m)); };
const KG_STEPS = []; for (let q = 0.25; q <= 10.001; q += 0.25) KG_STEPS.push(Math.round(q * 100) / 100);
for (const e of Object.values(obj(branchLookup.items))) {
  const p = num(e.price, NaN); if (!Number.isFinite(p)) continue;
  if (e.unit === 'kg') KG_STEPS.forEach(q => add(p * q)); else for (let q = 1; q <= 12; q++) add(p * q);
}
for (const levels of Object.values(obj(branchLookup.choices)))
  for (const L of arr(obj(levels).levels)) for (const o of arr(L.options)) add(num(o.price, NaN));
for (const e of Object.values(obj(allLookup.items))) { add(num(e.price_min, NaN)); add(num(e.price_max, NaN)); }
for (const i of items) { add(num(i.unit_price)); add(num(i.line_total)); add(num(i.base_price)); add(num(i.quantity)); }
[order.subtotal, order.discount_total, order.vat, order.delivery_fee, order.total, placedTotal].forEach(v => add(num(v, NaN)));
for (const a of arr(order.applied_offers)) add(num(a.amount, NaN));
toolNumbers.forEach(add);
for (const b of arr(allLookup.branches)) {
  ['delivery_fee', 'min_order', 'max_delivery_km', 'vat_percent', 'prep_minutes'].forEach(k => add(num(b[k], NaN)));
  [b.phone, b.address_ar, b.address_en, b.hours_text_ar, b.delivery_eta_text, b.price_note_ar, b.busy_reason, JSON.stringify(b.hours || {})].forEach(addDigits);
}
for (const z of arr(allLookup.zones)) ['delivery_fee', 'min_order', 'eta_min', 'eta_max'].forEach(k => add(num(z[k], NaN)));
for (const o of arr(allLookup.offers)) {
  ['value', 'max_discount', 'min_subtotal', 'free_item_qty'].forEach(k => add(num(o[k], NaN)));
  [o.title_ar, o.title_en, o.description_ar, o.description_en, o.time_from, o.time_to, o.ends_at].forEach(addDigits);
}
for (const n of arr(location.nearest)) add(num(n.km, NaN));
['delivery_fee', 'min_order', 'eta_min', 'eta_max', 'km'].forEach(k => add(num(zone[k], NaN)));
add(num(settings.max_delivery_km, NaN));
for (const v of Object.values(obj(profile.contacts))) addDigits(v);
[profile.about_ar, profile.about_en, profile.tone, profile.cuisine].forEach(addDigits);
for (const f of arr(profile.brand_facts)) addDigits(f);
for (const k of arr(allLookup.knowledge)) { addDigits(k.content_ar); addDigits(k.content_en); }
for (const o of arr(ctx.last_orders)) { add(num(o.total, NaN)); addDigits(o.order_no); for (const i of arr(o.items)) { add(num(i.line_total, NaN)); add(num(i.quantity, NaN)); } }
for (const a of arr(ctx.saved_addresses)) addDigits(a.text);
[100, 200, 250, 500, 750, 1000, 1500, 2000].forEach(add);
const textPool = [pre.customer_message, pre.history_text, JSON.stringify(state.customer || {}), str(obj(db.last_placed).order_no),
                  placedNo, pre.wa_id, JSON.stringify(ctx.last_orders || null), JSON.stringify(ctx.customer || null),
                  pre.facts_text, JSON.stringify(ctx.reservation || null), JSON.stringify(ctx.reservations_upcoming || null),
                  ...bookingTexts].map(toWesternDigits).join(' ');
for (const m of textPool.match(/\d+(?:\.\d+)?/g) || []) add(Number(m));

// ---- links the host may send ------------------------------------------------------------------
const domainOf = (u) => str(u).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/+$/, '');
const allowedLinks = [location.maps_url, profile.website, profile.instagram, profile.facebook, profile.tiktok, profile.google_maps_url]
  .concat(arr(allLookup.branches).map(b => b.maps_url)).concat(arr(settings.allowed_links))
  .map(domainOf).filter(Boolean);
const mapsHosts = ['google.com/maps', 'maps.google.com', 'goo.gl/maps', 'maps.app.goo.gl'];

const violations = [];
const joined = messages.join('\n');
if (!joined) violations.push('The reply was empty — write the reply.');

// placement claim without a placement (a sentence about a table booking is judged below, not here)
const BOOKING_WORDS = /(حجز|ترابيز|طاول|booking|reservation|\btable\b)/i;
const orderText = joined.split(/(?<=[.؟?!\n])/).filter(x => !BOOKING_WORDS.test(x)).join('');
const CLAIM = /(الأوردر|الاوردر|الطلب|طلبك|طلب حضرتك|أوردرك|اوردرك)[^.؟!\n]{0,25}(اتسجل|اتأكد|تم تأكيده|تم تسجيله|اتبعت للفرع|في الطريق)|(تم|اتعمل|اتم)\s*(تأكيد|تسجيل)\s*(الأوردر|الاوردر|الطلب)|order\s+(is|has been|was)\s+(placed|confirmed|sent)/i;
if (!placedNo && CLAIM.test(orderText)) {
  const known = [str(obj(db.last_placed).order_no)].concat(arr(ctx.last_orders).map(o => str(o.order_no))).filter(Boolean);
  if (!known.some(no => joined.includes(no))) {
    violations.push('The reply says the order is placed/confirmed, but place_order did NOT return PLACED this turn. Do not claim it — say what is actually next (e.g. the summary to confirm, or what is still missing).');
  }
}

// a table booking is confirmed by the branch team, never by the host
const BOOKED = /(تم|اتم|اتعمل)\s*(تأكيد\s*)?(الحجز|حجزك|حجز حضرتك|حجزكم)|(الحجز|حجزك|حجز حضرتك|حجزكم|الترابيزة|ترابيزتك)\s*(اتأكد|اتأكدت|اتثبت|مؤكد|متأكد|تمام ومتأكد)|اتحجز(ت|تلك|تلكم)?(?![\u0600-\u06FF])|حجزت(لك|لكم|لكو)|حجزنا(لك|لكم|لكو)|(booking|reservation|table)\s+(is|has been|was)\s+(confirmed|booked|reserved)|(you'?re|you are)\s+(all\s+)?booked/i;
const NOT_YET = /(?<!\p{L})(مش|مو|لسه|لسا|لما|عشان|علشان|بعد ما|أول ما|اول ما|not|once|until|will|pending)(?!\p{L})|(?<!\p{L})(هيت|هيأ|هيك|هير|هنت|هنأ|هنك|يأكد|يتأكد|بيأكد|للتأكيد)|n't/iu;
const confirmedBooking = arr(ctx.reservations_upcoming).some(x => str(obj(x).status) === 'confirmed');
if (!confirmedBooking) {
  const said = joined.split(/(?<=[.؟?!\n])/).find(x => BOOKED.test(x) && !NOT_YET.test(x));
  if (said) {
    violations.push('The reply says the table booking is booked or confirmed — it is not: ' + (bookingRef
      ? 'it was just SENT to the branch team, who will contact the customer to confirm it. Say that, with the reference number.'
      : 'only the branch team confirms a booking after it is sent. Say what is actually next.'));
  }
}

// internal leakage
const LEAK = /\bM\d{3,5}\b|\bP\d+-M\d{3,5}\b|\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-|\bmanage_cart\b|\bsave_customer_details\b|\bpending_id\b|\bline_id\b|\bmenu_id\b|\bset_branch\b|\bplace_order\b|\breorder_last\b|\bapply_code\b|\buse_saved_address\b|\bsaved_address\b|\bitems_json\b|\bdetails_json\b|\bmanage_reservation\b|\bsummary_text\b|\bref_no\b|\bready_for_summary\b|\bjson\b|\bundefined\b|\bNaN\b|\bnull\b/i;
const leak = joined.match(LEAK);
if (leak) violations.push(`The reply shows an internal code or word ("${leak[0]}") — say it in plain words for the customer.`);

// links
const links = joined.match(/https?:\/\/[^\s)]+/gi) || [];
for (const l of links) {
  const d = domainOf(l.replace(/[).,]+$/, ''));
  const ok = allowedLinks.some(a => a && (d.startsWith(a) || a.startsWith(d)))
          || (str(location.maps_url) && mapsHosts.some(h => d.startsWith(h)) && joined.includes(str(location.maps_url)));
  if (!ok) violations.push(`The link ${l} is not one of the restaurant's links — remove it.`);
}

// numbers
const scan = toWesternDigits(joined.replace(/https?:\/\/[^\s)]+/gi, ' ')).replace(/(\d),(\d{3})/g, '$1$2');
const bad = [];
for (const m of scan.match(/\d+(?:\.\d+)?/g) || []) {
  const n = Number(m);
  if (n < 20) continue;
  if (allowed.has(r2(n)) || allowed.has(Math.round(n))) continue;
  if (m.length >= 7 && textPool.includes(m)) continue;
  bad.push(m);
}
if (bad.length) violations.push(`These numbers are not prices, totals or details on file: ${[...new Set(bad)].join(', ')}. Use only the numbers in FACTS, the MENU and the tool results (or leave the number out).`);

// menu pictures
const pages = obj(media.menu_pages);
const pagesHere = branchId ? (num(pages[branchId]) || num(pages.all)) : num(pages.all);
let sendMenu = decision.send_menu_images === true || String(decision.send_menu_images).toLowerCase() === 'true';
if (sendMenu && !pagesHere) {
  sendMenu = false;
  if (/(المنيو|منيو|menu)/i.test(joined) && /(👆|👇|اهو|أهو|اهي|أهي|اتفضل|بعتلك|here)/i.test(joined)) {
    violations.push('There are no menu pictures to send — do not say they were sent; offer the dishes in text instead.');
  }
}

// dish photos: only dishes that have one, at most three
const photoCodes = new Set(arr(media.items_with_photos).map(str));
let photos = arr(decision.send_item_photos).map(x => (String(x).toUpperCase().match(/\bM\d{3,5}\b/) || [])[0]).filter(Boolean);
photos = [...new Set(photos.filter(c => photoCodes.has(c)))].slice(0, 3);
if (!photos.length && !sendMenu && /(صور[هةت]|الصوره|الصورة|photo|picture|pic)/i.test(joined) && /(👆|👇|اهي|أهي|اهو|أهو|اتفضل|بعتلك|here)/i.test(joined)) {
  violations.push('The reply says a photo is attached, but no photo is being sent (there may be none for that dish). Describe the dish instead.');
}

// length
if (joined.length > 2400) violations.push(`The reply is ${joined.length} characters — far too long for WhatsApp. Say less, or two short messages.`);

// summary flag only means something with a real cart
let showedSummary = decision.showed_order_summary === true || String(decision.showed_order_summary).toLowerCase() === 'true';
if (showedSummary && (!items.length || pending.length || placedNo)) showedSummary = false;

// a placement always carries its number
if (placedNo && !joined.includes(placedNo) && messages.length) {
  const en = /^[\x00-\x7F\s\p{P}\p{Emoji}]*$/u.test(messages[messages.length - 1]);
  messages[messages.length - 1] += (en ? `\nOrder number: ${placedNo}` : `\nرقم الأوردر: ${placedNo}`);
}

// a booking sent to the branch always carries its reference
if (bookingRef && !joined.includes(bookingRef) && messages.length) {
  const en = /^[\x00-\x7F\s\p{P}\p{Emoji}]*$/u.test(messages[messages.length - 1]);
  messages[messages.length - 1] += (en ? `\nBooking reference: ${bookingRef}` : `\nرقم طلب الحجز: ${bookingRef}`);
}

const handoff = obj(decision.handoff);
return [{
  json: {
    ...pre,
    decision: {
      reply_messages: messages,
      send_menu_images: sendMenu,
      send_item_photos: photos,
      showed_order_summary: showedSummary,
      handoff: { needed: handoff.needed === true || String(handoff.needed) === 'true', reason: str(handoff.reason) },
      language: str(decision.language) || null,
      memory_note: str(decision.memory_note)
    },
    tools_used: toolsUsed,
    tool_problems: toolProblems,
    order_placed_no: placedNo,
    booking_requested_ref: bookingRef,
    booking_confirmed: confirmedBooking,
    cart_items_after: items.length,
    pending_after: pending.length,
    branch_after: branchId || null,
    allowed_numbers: [...allowed],
    allowed_links: allowedLinks,
    hearts_stripped: heartsStripped,
    violations,
    needs_rewrite: violations.length > 0,
    agent_tokens: obj(agent.tokenUsage)
  }
}];

// =====================================================================
// EVERWAKE — Main · NODE: Build Rewrite Request
// Only runs when Check Reply found a broken rail. The rewrite model has
// NO tools: the cart and details are already saved, so nothing can be
// done twice. It keeps the host's intent and voice and fixes only what
// is listed.
// =====================================================================
const d = $input.first().json;
const msg = [
  d.facts_text,
  '',
  '================ MENU (prices are only these) ================',
  d.menu_text,
  '',
  '================ THE CHAT SO FAR ================',
  d.history_text || '(first message)',
  '',
  '================ CUSTOMER\'S LATEST MESSAGE ================',
  d.latest_text,
  '',
  '================ THE DRAFT REPLY ================',
  (d.decision.reply_messages || []).join('\n[[NEXT]]\n'),
  '',
  '================ WHAT IS WRONG WITH IT ================',
  (d.violations || []).map(v => '- ' + v).join('\n'),
  '',
  'Rewrite the draft so every problem above is fixed. Keep its intent, its language, its warmth and everything in it that was right. Change nothing else.'
].join('\n').replace(/\{/g, '(').replace(/\}/g, ')');   // prompt templates read { } as variables
return [{ json: { ...d, rewrite_prompt: msg, rewrite_started_at: new Date().toISOString() } }];

// =====================================================================
// EVERWAKE — Main · NODE: Finalize Rewrite
// Takes the rewrite, re-checks the same hard rails once, and if it is
// STILL broken, removes only the offending lines. No further model
// calls — this path is bounded on purpose.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
// ---- shared: Arabic-aware matching (same rules as everwake.norm in SQL) --
function normalizeArabic(s) {
  return String(s == null ? '' : s).toLowerCase()
    .replace(/[ً-ٰٟـ]/g, '')
    .replace(/[أإآٱ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه')
    .replace(/[٠-٩]/g, d => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)))
    .replace(/[^\p{L}\p{N}\s]/gu, ' ').replace(/\s+/g, ' ').trim();
}
const toWesternDigits = (s) => String(s == null ? '' : s).replace(/[٠-٩]/g, d => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)));
const d = $('Build Rewrite Request').first().json;
const res = $input.first().json || {};
const r2 = (n) => Math.round(Number(n) * 100) / 100;

let text = str(res.text ?? res.output ?? res.response ?? '');
let messages = [];
try {
  const s = text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  const a = s.indexOf('{'), z = s.lastIndexOf('}');
  const parsed = a !== -1 && z > a ? JSON.parse(s.slice(a, z + 1)) : null;
  messages = arr(parsed && parsed.reply_messages).map(str).filter(Boolean);
} catch (e) { messages = []; }
if (!messages.length && text && !/^\s*\{/.test(text)) messages = [text];
messages = messages.flatMap(m => m.split(/^\s*\[\[\s*NEXT\s*\]\]\s*$/m).map(x => x.trim()).filter(Boolean)).slice(0, 2)
  .map(m => m.replace(/\*\*(.+?)\*\*/g, '*$1*').replace(/^#{1,6}\s+/gm, '').trim());

const allowed = new Set((d.allowed_numbers || []).map(Number));
const LEAK = /\bM\d{3,5}\b|\bP\d+-M\d{3,5}\b|\b[0-9a-f]{8}-[0-9a-f]{4}-|manage_cart|save_customer_details|manage_reservation|summary_text|ref_no|pending_id|line_id|menu_id|set_branch|place_order|reorder_last|apply_code|saved_address/i;
const CLAIM = /(الأوردر|الاوردر|الطلب|طلبك|أوردرك|اوردرك)[^.؟!\n]{0,25}(اتسجل|اتأكد|تم تأكيده|تم تسجيله|اتبعت للفرع)|(تم|اتعمل)\s*(تأكيد|تسجيل)\s*(الأوردر|الاوردر|الطلب)|order\s+(is|has been|was)\s+(placed|confirmed)/i;
const allowedLinks = (d.allowed_links || []).map(String);
// the same booking rails as Check Reply: a booking sentence is not an order claim, and is never "confirmed" by the host
const BOOKING_WORDS = /(حجز|ترابيز|طاول|booking|reservation|\btable\b)/i;
const BOOKED = /(تم|اتم|اتعمل)\s*(تأكيد\s*)?(الحجز|حجزك|حجز حضرتك|حجزكم)|(الحجز|حجزك|حجز حضرتك|حجزكم|الترابيزة|ترابيزتك)\s*(اتأكد|اتأكدت|اتثبت|مؤكد|متأكد|تمام ومتأكد)|اتحجز(ت|تلك|تلكم)?(?![\u0600-\u06FF])|حجزت(لك|لكم|لكو)|حجزنا(لك|لكم|لكو)|(booking|reservation|table)\s+(is|has been|was)\s+(confirmed|booked|reserved)|(you'?re|you are)\s+(all\s+)?booked/i;
const NOT_YET = /(?<!\p{L})(مش|مو|لسه|لسا|لما|عشان|علشان|بعد ما|أول ما|اول ما|not|once|until|will|pending)(?!\p{L})|(?<!\p{L})(هيت|هيأ|هيك|هير|هنت|هنأ|هنك|يأكد|يتأكد|بيأكد|للتأكيد)|n't/iu;

function badLine(s) {
  if (LEAK.test(s)) return true;
  if (!d.order_placed_no && !BOOKING_WORDS.test(s) && CLAIM.test(s)) return true;
  if (!d.booking_confirmed && BOOKED.test(s) && !NOT_YET.test(s)) return true;
  for (const l of s.match(/https?:\/\/[^\s)]+/gi) || []) {
    const dom = l.toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '');
    if (!allowedLinks.some(a => a && (dom.startsWith(a) || a.startsWith(dom)))) return true;
  }
  const scan = toWesternDigits(s.replace(/https?:\/\/[^\s)]+/gi, ' '));
  for (const m of scan.match(/\d+(?:\.\d+)?/g) || []) {
    const n = Number(m);
    if (n >= 20 && !allowed.has(r2(n)) && !allowed.has(Math.round(n))) return true;
  }
  return false;
}

let source = 'rewrite';
const ref = d.booking_requested_ref;
if (!messages.length) { messages = d.decision.reply_messages || []; source = 'original'; }
// last resort: drop only the lines that still break a rail
messages = messages.map(m => m.split('\n').filter(line => !badLine(line)).join('\n').replace(/\n{3,}/g, '\n\n').trim()).filter(Boolean);
if (!messages.length) {
  const en = /English/.test(d.language_hint || '');
  messages = [en ? 'One moment please, let me check that for you 🙏' : 'ثانية واحدة أتأكدلك من الحتة دي 🙏'];
  source = 'fallback';
}
if (ref && !messages.join('\n').includes(ref)) {
  const en = /English/.test(d.language_hint || '');
  messages[messages.length - 1] += en ? `\nBooking reference: ${ref}` : `\nرقم طلب الحجز: ${ref}`;
}

return [{
  json: {
    ...d,
    decision: { ...d.decision, reply_messages: messages },
    repair_used: true,
    repair_source: source,
    needs_rewrite: false,
    rewrite_ms: d.rewrite_started_at ? Date.now() - new Date(d.rewrite_started_at).getTime() : 0
  }
}];

// =====================================================================
// EVERWAKE — Main · NODE: Build Persist Payload
// The cart is written by manage_cart and the details by
// save_customer_details. This write is the turn's own record: memory
// notes, pictures sent, the review fingerprint when the summary was
// shown, a handoff for the inbox, telemetry, unlock and buffer cleanup.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
const d = $input.first().json;
let state = {};
try { state = obj(row($('Read Back State').first().json).state); } catch (e) { state = {}; }
const ledger = obj(state.ledger);
const nowIso = new Date().toISOString();
const dec = obj(d.decision);

const stage = d.order_placed_no ? 'placed'
  : (d.pending_after ? 'answering_choices'
  : (d.cart_items_after ? (arr(d.missing_details).length ? 'building_or_details' : 'reviewing') : 'discovery'));

const statePatch = {
  last_turn_at: nowIso,
  phase: stage,
  last_language: dec.language || null
};
const note = str(dec.memory_note);
if (note) statePatch.memory_notes = arr(state.memory_notes).concat([note.slice(0, 220)]).slice(-12);
const handoff = obj(dec.handoff);
if (handoff.needed) statePatch.handoff = { needed: true, reason: str(handoff.reason), at: nowIso };

const ledgerPatch = { last_reply_at: nowIso };
const menuKey = d.branch_after || 'all';
if (dec.send_menu_images) {
  const sent = arr(ledger.menu_sent_branches).map(str);
  if (!sent.includes(menuKey)) ledgerPatch.menu_sent_branches = sent.concat([menuKey]);
}
if (arr(dec.send_item_photos).length) {
  ledgerPatch.photos_sent = [...new Set(arr(ledger.photos_sent).map(str).concat(arr(dec.send_item_photos)))].slice(-20);
}

const tokens = obj(d.agent_tokens);
const durationTotal = Date.now() - new Date(d.turn_started_at).getTime();
const logRow = {
  order_stage: stage,
  cart_action: arr(d.tools_used).filter(t => t === 'manage_cart').length ? 'tool_call' : 'none',
  qa_passed: !arr(d.violations).length,
  repair_used: d.repair_used === true,
  llm_calls: (d.brain && d.brain.used ? 1 : 0) + 1 + arr(d.tools_used).length + (d.repair_used ? 1 : 0),
  duration_total_ms: durationTotal,
  duration_llm_ms: d.agent_started_at ? Date.now() - new Date(d.brain_started_at || d.agent_started_at).getTime() : 0,
  prompt_tokens: Number(tokens.promptTokens || 0),
  completion_tokens: Number(tokens.completionTokens || 0),
  input: { message: d.customer_message, buffered_count: d.buffered_count, has_location: d.has_location, branch: d.branch_id },
  output: {
    messages: arr(dec.reply_messages),
    brain: d.brain || null,
    tools_used: arr(d.tools_used),
    tool_problems: arr(d.tool_problems).slice(0, 10),
    violations: arr(d.violations),
    repair_source: d.repair_source || null,
    order_placed_no: d.order_placed_no || null,
    showed_order_summary: !!dec.showed_order_summary,
    send_menu_images: !!dec.send_menu_images,
    send_item_photos: arr(dec.send_item_photos),
    handoff,
    brief_chars: d.brief_chars, agent_prompt_chars: d.agent_prompt_chars
  }
};

return [{
  json: {
    ...d,
    b64_persist: b64({
      tenant_id: d.tenant_id, wa_id: d.wa_id, run_id: d.run_id,
      state_patch: statePatch, ledger_patch: ledgerPatch, log_row: logRow,
      save_review: !!dec.showed_order_summary,
      handoff: { needed: !!handoff.needed, reason: str(handoff.reason) },
      language: dec.language || null
    }),
    b64_media: b64({
      tenant_id: d.tenant_id, branch_id: d.branch_after || null,
      send_menu: !!dec.send_menu_images, item_codes: arr(dec.send_item_photos)
    }),
    duration_total_ms: durationTotal
  }
}];

// =====================================================================
// EVERWAKE — Main · NODE: Prepare Outbound Messages
// One item per WhatsApp message, each carrying the restaurant's own
// WhatsApp connection. Pictures go FIRST (menu pages, then dish photos
// with their name and price), then the text that refers to them.
// If a person took the conversation over — or the agent was switched
// off — while the model was thinking, nothing is sent.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
const d = $('Build Persist Payload').first().json;
const persisted = row($('Persist Turn + Unlock').first().json);
const intake = row($('Intake').first().json);
const mediaRow = row($input.first().json);
const dec = obj(d.decision);

if (persisted.mode === 'human' || persisted.agent_enabled === false) return [];

const channel = obj(intake.channel);
const replyTo = str(intake.reply_to) || str(d.wa_id);
const sym = str(obj(obj(row($('Load Turn Context').first().json).all_lookup).tenant).currency_symbol) || 'ج';
const base = { run_id: d.run_id, tenant_id: d.tenant_id, wa_id: d.wa_id, reply_to: replyTo,
               base_url: str(channel.base_url), instance: str(channel.instance), api_key: str(channel.api_key) };
const out = [];

for (const p of arr(mediaRow.menu_pages)) {
  out.push({ ...base, kind: p.kind === 'pdf' ? 'document' : 'image', media_url: p.url,
             mime: p.mime || (p.kind === 'pdf' ? 'application/pdf' : 'image/jpeg'),
             file_name: p.file_name || (p.kind === 'pdf' ? 'menu.pdf' : 'menu.jpg'), caption: p.caption || '',
             log_text: `[menu ${p.kind === 'pdf' ? 'PDF' : 'picture'}]`, delay_ms: 400 });
}
for (const ph of arr(mediaRow.item_photos)) {
  const unit = ph.unit === 'kg' ? ' للكيلو' : '';
  out.push({ ...base, kind: 'image', media_url: ph.url, mime: ph.mime || 'image/jpeg', file_name: `${ph.code}.jpg`,
             caption: `*${ph.name}*${ph.price != null ? ` — ${fmt(ph.price)}${sym}${unit}` : ''}`,
             log_text: `[photo: ${ph.name}]`, delay_ms: 400 });
}
for (const text of arr(dec.reply_messages).filter(Boolean).slice(0, 2)) {
  out.push({ ...base, kind: 'text', text, log_text: text,
             // Evolution's own typing simulation blocks for delay_ms, so keep it short
             delay_ms: Math.min(1200, Math.max(300, Math.round(text.length * 8))) });
}
return out.map((x, i) => ({ json: { ...x, index: i } }));

// =====================================================================
// EVERWAKE — Main · NODE: Record Send
// What Evolution said about one outgoing message → one row in messages,
// so the dashboard shows exactly what the customer received.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
const item = $('Outbound Loop').first().json;
const r = $input.first().json || {};
const body = obj(r.body && typeof r.body === 'object' ? r.body : r);
const id = str(obj(body.key).id) || null;
const ok = !!id && !r.error;
const err = ok ? null : str(obj(r.error).message || r.error || body.message || 'WhatsApp did not confirm the message').slice(0, 300);

return [{
  json: {
    b64_log: b64({
      tenant_id: item.tenant_id, wa_id: item.wa_id, run_id: item.run_id, sender: 'agent',
      kind: item.kind, body: item.kind === 'text' ? item.text : item.log_text,
      media_url: item.media_url || null, media_mime: item.mime || null,
      external_id: id, ok, error: err, meta: { caption: item.caption || undefined }
    })
  }
}];

// =====================================================================
// EVERWAKE — Main · NODE: Build Order Ticket
// A placed order becomes one WhatsApp message to the branch's operations
// number (branches.ops_whatsapp, else the restaurant's ops_whatsapp).
// The live order board in the dashboard rings either way; this is the
// second channel for kitchens that work from a phone. No number, or
// tickets switched off → nothing is sent.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const money = (n) => Math.round(num(n) * 100) / 100;
const fmt = (n) => String(money(n));
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
const o = row($input.first().json);
const intake = row($('Intake').first().json);
const ops = String(o.ops_whatsapp || '').replace(/\D/g, '');
if (!o.order_no || o.send_ticket === false || ops.length < 10) return [];

const c = obj(o.customer);
const SYM = str(o.currency_symbol) || 'ج';
const m = (n) => `${fmt(n)}${SYM}`;
const UNIT = { kg: 'كيلو', piece: 'قطعة', person: 'فرد' };
const PAY = { cash: 'كاش', card: 'فيزا/كارت', wallet: 'محفظة', instapay: 'إنستاباي' };

const lines = arr(obj(o.cart).items).map(i => {
  const ch = arr(i.choices).map(x => arr(x.selected).map(s => (s.name || s) + (s.extra_charge ? ' (+رسوم تسوية)' : '')).join(' + ')).filter(Boolean).join('، ');
  const q = UNIT[i.unit] ? `${fmt(i.quantity)} ${UNIT[i.unit]}` : `× ${fmt(i.quantity)}`;
  return `• ${i.display_name || i.item_name} ${q}${ch ? ' — ' + ch : ''}${i.notes ? ' — ملاحظة: ' + i.notes : ''} = ${i.gift ? 'هدية' : m(i.line_total)}`;
});
const loc = obj(o.location);
const offers = arr(o.applied_offers).filter(a => num(a.amount) > 0).map(a => `${a.title}: −${m(a.amount)}`);
const text = [
  `🧾 أوردر جديد ${o.order_no} — فرع ${o.branch_name || '-'}`,
  '',
  ...lines,
  '',
  `المجموع: ${m(o.subtotal)}`,
  ...offers.map(x => 'خصم ' + x),
  o.vat == null ? 'الضريبة/الرسوم: يحددها الفرع' : `الضريبة ${fmt(o.vat_percent)}%: ${m(o.vat)}`,
  `التوصيل: ${o.delivery_fee == null ? (o.delivery_method === 'pickup' ? '—' : 'يحدده الفرع') : m(o.delivery_fee)}`,
  `الإجمالي: ${m(o.total)}`,
  '',
  `الاسم: ${c.full_name || '-'}`,
  `الموبايل: ${c.phone || (intake.phone_hidden ? '-' : o.wa_id)}${c.alt_phone ? ' / ' + c.alt_phone : ''}`,
  `${o.delivery_method === 'pickup' ? 'استلام من الفرع' : 'توصيل'} — الدفع: ${PAY[o.payment_method] || o.payment_method || '-'}`,
  o.delivery_method === 'pickup' ? '' : `العنوان: ${o.address_text || '-'}`,
  o.zone_name ? `منطقة التوصيل: ${o.zone_name}` : '',
  loc.maps_url ? `اللوكيشن: ${loc.maps_url}` : '',
  o.notes ? `ملاحظات: ${o.notes}` : '',
  c.phone ? `واتساب العميل: wa.me/${String(c.phone).replace(/\D/g, '')}` : 'واتساب العميل: الرقم مخفي — رد عليه من الداشبورد'
].filter(x => x !== '').join('\n');

const ch = obj(intake.channel);
return [{ json: { ops_number: ops, text, base_url: str(ch.base_url), instance: str(ch.instance), api_key: str(ch.api_key) } }];
